import { loadNative } from '../mochinode/index.js';
import { EventEmitter } from '../mochievents/index.js';
import { setTimeout } from '../mochitimers/index.js';
import { TextEncoder, TextDecoder } from '../mochiglobals/index.js';

let native = null;
let nativeFailure = null;
try {
    native = await loadNative('mochiws');
} catch (error) {
    nativeFailure = error;
}

function ensure() {
    if (native) return native;
    throw new Error(`mochiws: native plugin unavailable: ${nativeFailure ? nativeFailure.message : 'not loaded'}`);
}

function toBytes(data) {
    if (data == null) return new Uint8Array(0);
    if (data instanceof Uint8Array) return data;
    if (Array.isArrayBuffer && ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    if (data instanceof ArrayBuffer) return new Uint8Array(data);
    if (Array.isArray(data)) return Uint8Array.from(data);
    if (typeof data === 'string') {
        const out = new Uint8Array(data.length);
        for (let i = 0; i < data.length; i++) out[i] = data.charCodeAt(i) & 0xff;
        return out;
    }
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer && Buffer.isBuffer(data)) return new Uint8Array(data);
    return new Uint8Array(0);
}

function hexFromBytes(bytes) {
    let out = '';
    for (let i = 0; i < bytes.length; i++) out += bytes[i].toString(16).padStart(2, '0');
    return out;
}

function bytesFromHex(hex) {
    const s = String(hex || '').replace(/[^0-9a-fA-F]/g, '');
    const out = new Uint8Array(Math.floor(s.length / 2));
    for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(i*2, i*2+2), 16) || 0;
    return out;
}

export const CONNECTING = 0;
export const OPEN = 1;
export const CLOSING = 2;
export const CLOSED = 3;

export class WebSocket extends EventEmitter {
    static CONNECTING = CONNECTING;
    static OPEN = OPEN;
    static CLOSING = CLOSING;
    static CLOSED = CLOSED;

    constructor(url, protocols, options) {
        super();
        if (protocols && typeof protocols === 'object' && !Array.isArray(protocols)) {
            options = protocols;
            protocols = undefined;
        }
        this.url = String(url);
        this.protocols = protocols;
        this.options = options || {};
        this.readyState = CONNECTING;
        this.binaryType = 'nodebuffer';
        this.bufferedAmount = 0;
        this.extensions = '';
        this.protocol = '';
        this._handle = null;
        this._pollTimer = null;
        this._closed = false;
        this.onopen = null;
        this.onclose = null;
        this.onerror = null;
        this.onmessage = null;
        this.onping = null;
        this.onpong = null;
        this.on('error', () => {});
        this._connect();
    }

    _emitCompat(event, ...args) {
        this.emit(event, ...args);
        const handler = this['on' + event];
        if (typeof handler === 'function') {
            try {
                if (event === 'message') handler({ data: args[0], type: 'message', target: this });
                else if (event === 'close') handler({ code: args[0]?.code ?? 1000, reason: args[0]?.reason ?? '', wasClean: true, target: this });
                else if (event === 'error') handler(args[0] instanceof Error ? args[0] : { error: args[0], message: String(args[0]?.message || args[0]), target: this });
                else handler({ target: this });
            } catch {}
        }
    }

    _connect() {
        try {
            this._handle = String(ensure().connect(this.url));
            // Defer the open emission + poll start so listeners attached after
            // construction (onopen / on('open')) see the event, like Node.
            setTimeout(() => {
                if (this._closed || !this._handle) return;
                this.readyState = OPEN;
                this._emitCompat('open');
                this._startPoll();
            }, 0);
        } catch (error) {
            this.readyState = CLOSED;
            this._emitCompat('error', error);
            this._emitCompat('close', { code: 1006, reason: String(error?.message || error) });
        }
    }

    _startPoll() {
        if (this._pollTimer || this._closed) return;
        const tick = () => {
            if (this._closed || !this._handle) return;
            try {
                const events = poll(this._handle);
                for (const ev of events) {
                    if (!ev) continue;
                    if (ev.type === 'message' || ev.type === 'text') {
                        const bytes = bytesFromHex(ev.data || '');
                        const isText = ev.type === 'text' || ev.isText === true;
                        const data = isText ? new TextDecoder().decode(bytes) : (this.binaryType === 'arraybuffer' ? bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) : bytes);
                        this._emitCompat('message', data);
                    } else if (ev.type === 'close') {
                        this._doClose(ev.code || 1000, ev.reason || '');
                    } else if (ev.type === 'error') {
                        this._emitCompat('error', new Error(ev.message || 'mochiws error'));
                    } else if (ev.type === 'ping') {
                        this._emitCompat('ping', bytesFromHex(ev.data || ''));
                    } else if (ev.type === 'pong') {
                        this._emitCompat('pong', bytesFromHex(ev.data || ''));
                    }
                }
            } catch (error) {
                this._emitCompat('error', error);
            }
        };
        this._pollTimer = setInterval(tick, 20);
        if (this._pollTimer && typeof this._pollTimer.unref === 'function') this._pollTimer.unref();
    }

    send(data, cb) {
        try {
            if (this.readyState !== OPEN || !this._handle) throw new Error('WebSocket is not open');
            const isText = typeof data === 'string';
            const bytes = isText ? new TextEncoder().encode(data) : toBytes(data);
            const rc = send(this._handle, bytes, isText);
            if (rc < 0) throw new Error('mochiws send failed');
            if (cb) cb();
            return true;
        } catch (error) {
            if (cb) cb(error);
            else this._emitCompat('error', error);
            return false;
        }
    }

    close(code = 1000, reason = '') {
        if (this.readyState === CLOSING || this.readyState === CLOSED) return;
        this.readyState = CLOSING;
        this._doClose(code, reason);
    }

    _doClose(code = 1000, reason = '') {
        if (this._closed) return;
        this._closed = true;
        if (this._pollTimer) { clearInterval(this._pollTimer); this._pollTimer = null; }
        const handle = this._handle;
        this._handle = null;
        try { if (handle) close(handle); } catch {}
        this.readyState = CLOSED;
        this._emitCompat('close', { code, reason: String(reason || '') });
    }

    terminate() { this._doClose(1006, 'terminated'); }
    ping() { /* no-op: native may not support */ }
    pong() { /* no-op */ }
    setMaxListeners() { return this; }
}

export function connect(url, protocols, options) { return new WebSocket(url, protocols, options); }
export function send(handleOrWs, bytes, isText = false) {
    if (handleOrWs instanceof WebSocket) return handleOrWs.send(bytes);
    const hex = hexFromBytes(toBytes(bytes));
    return Number(ensure().send(String(handleOrWs), hex, isText ? 1 : 0));
}
export function poll(handle) {
    const raw = String(ensure().poll(String(handle)));
    try { return JSON.parse(raw); } catch { return []; }
}
export function close(handle) {
    if (handle instanceof WebSocket) return handle.close();
    return Number(ensure().close(String(handle)));
}
export function httpGet(url) {
    const raw = String(ensure().httpGet(String(url)));
    const statusKey = '"status":';
    const statusAt = raw.indexOf(statusKey);
    const status = statusAt >= 0 ? Number(raw.slice(statusAt + statusKey.length, raw.indexOf(',', statusAt))) : 0;
    const bodyKey = '"bodyHex":"';
    const bodyAt = raw.indexOf(bodyKey);
    const bodyEnd = bodyAt >= 0 ? raw.indexOf('"', bodyAt + bodyKey.length) : -1;
    return {
        status: status,
        ok: raw.indexOf('"ok":true') >= 0,
        headers: {},
        bodyHex: bodyEnd > bodyAt ? raw.slice(bodyAt + bodyKey.length, bodyEnd) : '',
    };
}
export const isNativeReady = () => !!native;
export const nativeError = () => nativeFailure;
export class WebSocketServer { constructor(){ throw new Error('mochiws: WebSocketServer unavailable'); } }
WebSocket.WebSocket = WebSocket;
WebSocket.Server = WebSocketServer;
WebSocket.WebSocketServer = WebSocketServer;
export default WebSocket;
export { WebSocket as WebSocketClient };
